import { SUBJECTS, STATUSES, makeInitialData, uid, localDate, addDays, scoreSummary, nextReviewDate, weeklyStats, parseBackup, validateData } from './model.mjs';

const KEY = 'gaokao-2028-data-v1';
const navItems = [
  ['today', '⌂', '今日总览'], ['scores', '▣', '六科成绩'], ['tasks', '✓', '每日任务'],
  ['timer', '◷', '学习计时'], ['mistakes', '◇', '错题本'], ['points', '✦', '知识点'],
  ['stats', '▥', '每周统计'], ['backup', '⇅', '备份恢复'],
];
let data = loadData();
let currentPage = location.hash.slice(1) || 'today';
let timerTick = null;

function loadData() {
  try { const raw = localStorage.getItem(KEY); return raw ? validateData(JSON.parse(raw)) : makeInitialData(); }
  catch { return makeInitialData(); }
}
function save() { localStorage.setItem(KEY, JSON.stringify(data)); }
function subject(id) { return data.settings.subjects.find(s => s.id === id) || data.settings.subjects[0]; }
function subjectName(id) { return subject(id)?.name || '未分类'; }
function esc(value) { return String(value ?? '').replace(/[&<>'"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[ch])); }
function dateLabel(iso) { const [y, m, d] = iso.split('-'); return `${m}月${d}日`; }
function showNotice(message, type = 'ok') { const el = document.querySelector('#notice'); el.textContent = message; el.hidden = false; el.dataset.type = type; clearTimeout(showNotice.timeout); showNotice.timeout = setTimeout(() => { el.hidden = true; }, 2800); }
function options(selected = '') { return data.settings.subjects.map(s => `<option value="${s.id}" ${s.id === selected ? 'selected' : ''}>${esc(s.name)}</option>`).join(''); }
function setDateDefaults() {
  const today = localDate();
  for (const selector of ['#score-form input[name=date]', '#task-form input[name=date]', '#task-filter-date']) { const el = document.querySelector(selector); if (el && !el.value) el.value = today; }
  const review = document.querySelector('#mistake-form input[name=nextReview]'); if (review && !review.value) review.value = addDays(today, 1);
}
function populateSelects() {
  for (const id of ['score-subject','task-subject','timer-subject','mistake-subject','point-subject']) { const el = document.getElementById(id); if (el) { const prev = el.value; el.innerHTML = options(prev || (id === 'timer-subject' ? 'math' : '')); if (prev) el.value = prev; } }
  const filter = document.querySelector('#mistake-filter'); if (filter) { const prev = filter.value || 'all'; filter.innerHTML = `<option value="all">全部科目</option>${options()}`; filter.value = prev; }
}
function renderNav() {
  const make = (mobile = false) => navItems.map(([id, icon, label]) => `<button class="${mobile ? 'bottom-link' : 'nav-link'} ${currentPage === id ? 'active' : ''}" data-page="${id}" type="button"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('');
  document.querySelector('#side-nav').innerHTML = make(); document.querySelector('#bottom-nav').innerHTML = make(true);
  document.querySelectorAll('[data-page]').forEach(el => el.addEventListener('click', () => go(el.dataset.page)));
}
function go(page) { if (!navItems.some(x => x[0] === page)) page = 'today'; currentPage = page; history.replaceState(null, '', `#${page}`); document.querySelectorAll('.page').forEach(el => { el.hidden = el.id !== `page-${page}`; }); const item = navItems.find(x => x[0] === page); document.querySelector('#page-title').textContent = item[2]; renderNav(); renderAll(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function renderToday() {
  const today = localDate(); const todayTasks = data.tasks.filter(t => t.date === today); const sessions = data.sessions.filter(s => s.date === today);
  const done = todayTasks.filter(t => t.done).length; document.querySelector('#today-task-count').textContent = `${done}/${todayTasks.length}`; document.querySelector('#today-minutes').innerHTML = `${sessions.reduce((n,s) => n + s.minutes, 0)}<em> 分钟</em>`;
  document.querySelector('#due-count').textContent = data.mistakes.filter(m => m.nextReview <= today).length;
  document.querySelector('#today-task-list').innerHTML = todayTasks.length ? `<div class="mini-list">${todayTasks.slice(0, 4).map(t => `<div class="mini-task ${t.done ? 'done' : ''}"><span>${t.done ? '✓' : '○'}</span><span>${esc(t.title)}</span><span class="subject-pill">${esc(subjectName(t.subjectId))}</span></div>`).join('')}</div>` : '<div class="empty">今天还没有任务。<br>把第一个小目标写下来吧。</div>';
  renderMiniTimer();
}
function renderMiniTimer() { const running = data.timer.runningSince !== null; const sec = timerSeconds(); document.querySelector('#mini-timer').innerHTML = `<div class="mini-stat">${formatTime(sec)} <small>${running ? '正在专注' : '准备开始'}</small></div>`; }
function renderScores() {
  const summary = scoreSummary(data); document.querySelector('#score-total').textContent = summary.total ?? data.settings.baseline; document.querySelector('#score-total-note').textContent = summary.total === null ? '根据你的描述，六科实测成绩待录入' : '六科最新成绩合计';
  document.querySelector('#subject-grid').innerHTML = data.settings.subjects.map(s => { const latest = summary.latest[s.id]; const pct = latest ? Math.min(100, latest.score / s.max * 100) : 0; return `<article class="subject-card card"><div class="subject-card-head"><span class="subject-icon">${esc(s.name.slice(0,1))}</span><h3>${esc(s.name)}</h3></div><div class="current">${latest ? latest.score : '—'} <small>/ ${s.max}</small></div><div class="target">目标 ${s.target} 分</div><div class="bar"><span style="width:${pct}%"></span></div><div class="subject-edit"><label>修改目标<input data-target-subject="${s.id}" type="number" min="0" max="${s.max}" value="${s.target}"></label><button data-save-target="${s.id}" type="button">保存</button></div></article>`; }).join('');
  document.querySelector('#score-history').innerHTML = data.scores.length ? data.scores.slice().sort((a,b) => b.createdAt-a.createdAt).slice(0, 20).map(x => `<div class="list-card"><div class="list-main"><p class="list-title">${esc(subjectName(x.subjectId))} · ${x.score} 分</p><div class="list-meta"><span>${dateLabel(x.date)}</span><span class="subject-pill">满分 ${subject(x.subjectId).max}</span></div></div><button class="small-button danger" data-delete="score" data-id="${x.id}" type="button">删除</button></div>`).join('') : '<div class="empty">还没有成绩记录，先录入一次阶段测验吧。</div>';
}
function renderTasks() {
  const filter = document.querySelector('#task-filter-date')?.value || localDate(); const tasks = data.tasks.filter(t => t.date === filter).sort((a,b) => Number(a.done)-Number(b.done));
  document.querySelector('#task-list').innerHTML = tasks.length ? tasks.map(t => `<article class="list-card task-row ${t.done ? 'done' : ''}"><input class="task-check" type="checkbox" data-toggle-task="${t.id}" ${t.done ? 'checked' : ''} aria-label="完成任务"><div class="list-main"><p class="list-title">${esc(t.title)}</p><div class="list-meta"><span class="subject-pill">${esc(subjectName(t.subjectId))}</span><span>预计 ${t.plannedMinutes} 分钟</span></div></div><div class="list-actions"><button class="small-button" data-start-task="${t.id}" type="button">开始计时</button><button class="small-button danger" data-delete="task" data-id="${t.id}" type="button">删除</button></div></article>`).join('') : '<div class="empty">这一天还没有任务。<br>添加一个 20～40 分钟能完成的小目标。</div>';
}
function timerSeconds() { return Math.min(86400, data.timer.accumulatedSec + (data.timer.runningSince ? Math.max(0, Math.floor((Date.now() - data.timer.runningSince) / 1000)) : 0)); }
function formatTime(sec) { sec = Math.max(0, Math.floor(sec)); return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`; }
function renderTimer() { const running = data.timer.runningSince !== null; document.querySelector('#timer-display').textContent = formatTime(timerSeconds()); document.querySelector('#timer-state').textContent = running ? `正在学习 · ${subjectName(data.timer.subjectId)}` : '尚未开始'; document.querySelector('#timer-toggle').textContent = running ? '暂停计时' : '开始计时'; document.querySelector('#timer-subject').value = data.timer.subjectId; document.querySelector('#session-list').innerHTML = data.sessions.length ? data.sessions.slice().reverse().slice(0, 15).map(x => `<div class="list-card"><div class="list-main"><p class="list-title">${esc(subjectName(x.subjectId))} · ${x.minutes} 分钟</p><div class="list-meta"><span>${dateLabel(x.date)}</span><span>${x.note ? esc(x.note) : '专注学习'}</span></div></div><button class="small-button danger" data-delete="session" data-id="${x.id}" type="button">删除</button></div>`).join('') : '<div class="empty">结束一次计时后，学习记录会显示在这里。</div>'; clearInterval(timerTick); if (running) timerTick = setInterval(() => { renderTimer(); renderMiniTimer(); }, 1000); }
function renderMistakes() { const filter = document.querySelector('#mistake-filter')?.value || 'all'; const today = localDate(); const list = data.mistakes.filter(x => filter === 'all' || x.subjectId === filter).sort((a,b) => a.nextReview.localeCompare(b.nextReview)); document.querySelector('#mistake-filter-hint').textContent = `${list.filter(x => x.nextReview <= today).length} 道到期`; document.querySelector('#mistake-list').innerHTML = list.length ? list.map(x => { const due = x.nextReview <= today; return `<article class="list-card"><div class="list-main"><p class="list-title">${esc(subjectName(x.subjectId))} · ${esc(x.question)}</p><div class="list-meta"><span class="subject-pill">${esc(subjectName(x.subjectId))}</span><span class="status-pill ${due ? 'due' : ''}">${due ? '今天应复习' : `下次 ${dateLabel(x.nextReview)}`}</span><span>已复习 ${x.reviewCount} 次</span></div><div class="mistake-body"><p class="detail"><strong>正确思路：</strong>${esc(x.answer || '尚未补充')}</p><p class="detail"><strong>错误原因：</strong>${esc(x.reason || '尚未补充')}</p></div></div><div class="list-actions"><button class="small-button primary" data-review-mistake="${x.id}" type="button">完成复习</button><button class="small-button danger" data-delete="mistake" data-id="${x.id}" type="button">删除</button></div></article>`; }).join('') : '<div class="empty">还没有错题。做错一道，就认真留下它。</div>'; }
function renderPoints() { const counts = Object.fromEntries(STATUSES.map(s => [s, data.points.filter(x => x.status === s).length])); document.querySelector('#point-summary').innerHTML = STATUSES.map(s => `<div class="status-box card"><strong>${counts[s]}</strong><span>${s}</span></div>`).join(''); document.querySelector('#point-count').textContent = `共 ${data.points.length} 个知识点`; document.querySelector('#point-list').innerHTML = data.points.length ? data.points.map(x => `<article class="list-card"><div class="list-main"><p class="list-title">${esc(x.title)}</p><div class="list-meta"><span class="subject-pill">${esc(subjectName(x.subjectId))}</span><span class="status-pill ${x.status === '已掌握' ? 'mastered' : ''}">${x.status}</span></div></div><div class="list-actions"><select data-point-status="${x.id}" aria-label="修改掌握状态">${STATUSES.map(s => `<option ${s === x.status ? 'selected' : ''}>${s}</option>`).join('')}</select><button class="small-button danger" data-delete="point" data-id="${x.id}" type="button">删除</button></div></article>`).join('') : '<div class="empty">从数学、物理、化学各写一个最薄弱的知识点开始。</div>'; }
function renderStats() { const stats = weeklyStats(data); const days = ['一','二','三','四','五','六','日']; const max = Math.max(30, ...stats.daily.map(x => x.minutes)); const first = stats.daily[0].date; const last = stats.daily[6].date; document.querySelector('#week-range').textContent = `${dateLabel(first)} — ${dateLabel(last)}`; document.querySelector('#week-minutes').innerHTML = `${stats.minutes}<em> 分钟</em>`; document.querySelector('#week-completed').textContent = stats.completed; document.querySelector('#week-due').textContent = `本周共 ${stats.due} 项`; document.querySelector('#mastered-count').textContent = data.points.filter(x => x.status === '已掌握').length; document.querySelector('#point-count').textContent = `共 ${data.points.length} 个知识点`; document.querySelector('#week-chart').innerHTML = stats.daily.map((x,i) => `<div class="day-bar"><span class="value">${x.minutes || ''}</span><span class="bar" style="height:${Math.max(x.minutes ? 8 : 3, x.minutes/max*160)}px"></span><span class="day">周${days[i]}</span></div>`).join(''); const suggestion = stats.minutes < 300 ? '本周记录还不到 5 小时。先给每天安排一个 25 分钟的数学基础任务，完成比计划更重要。' : stats.completed < 5 ? '专注时间不错，可以把大任务拆成更具体的清单，完成感会更清楚。' : '节奏保持得很好。复习本周错题，并把一个“学习中”的知识点推进到“已掌握”。'; document.querySelector('#week-suggestion').textContent = suggestion; }
function renderBackup() { const bytes = new Blob([JSON.stringify(data)]).size; document.querySelector('#storage-status').textContent = `当前本机已保存 ${data.scores.length} 条成绩、${data.tasks.length} 个任务、${data.mistakes.length} 道错题、${data.sessions.length} 条学习记录（约 ${(bytes/1024).toFixed(1)} KB）。`; }
function renderAll() { populateSelects(); setDateDefaults(); renderToday(); renderScores(); renderTasks(); renderTimer(); renderMistakes(); renderPoints(); renderStats(); renderBackup(); }

function handleSubmit(event) {
  event.preventDefault(); const form = event.target; const fd = new FormData(form); const today = localDate();
  if (form.id === 'score-form') { const s = subject(fd.get('subjectId')); const score = Number(fd.get('score')); if (score > s.max) return showNotice(`${s.name}满分是 ${s.max} 分`, 'error'); data.scores.push({ id: uid(), subjectId: s.id, score, date: fd.get('date'), createdAt: Date.now() }); showNotice('成绩已保存'); }
  if (form.id === 'task-form') { data.tasks.push({ id: uid(), title: fd.get('title').trim(), subjectId: fd.get('subjectId'), date: fd.get('date'), plannedMinutes: Number(fd.get('plannedMinutes')), done: false }); showNotice('任务已添加'); }
  if (form.id === 'mistake-form') { data.mistakes.push({ id: uid(), subjectId: fd.get('subjectId'), question: fd.get('question').trim(), answer: fd.get('answer').trim(), reason: fd.get('reason').trim(), createdDate: today, nextReview: fd.get('nextReview'), reviewCount: 0 }); showNotice('错题已加入'); }
  if (form.id === 'point-form') { data.points.push({ id: uid(), subjectId: fd.get('subjectId'), title: fd.get('title').trim(), status: fd.get('status') }); showNotice('知识点已添加'); }
  save(); form.reset(); renderAll(); }
function stopTimer(saveSession = true) { const sec = timerSeconds(); if (data.timer.runningSince !== null) { data.timer.accumulatedSec = 0; data.timer.runningSince = null; if (saveSession && sec >= 60) { data.sessions.push({ id: uid(), subjectId: data.timer.subjectId, date: localDate(), minutes: Math.floor(sec / 60), note: '计时器学习' }); showNotice(`已记录 ${Math.floor(sec/60)} 分钟`); } else if (saveSession) showNotice('本次不足 1 分钟，没有写入统计', 'error'); } else if (saveSession && data.timer.accumulatedSec >= 60) { data.sessions.push({ id: uid(), subjectId: data.timer.subjectId, date: localDate(), minutes: Math.floor(data.timer.accumulatedSec / 60), note: '计时器学习' }); data.timer.accumulatedSec = 0; showNotice('已记录学习时间'); } save(); renderAll(); }
function exportBackup() { const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `高考提分备份-${localDate()}.json`; a.click(); URL.revokeObjectURL(a.href); showNotice('备份文件已下载'); }
function bindEvents() {
  document.querySelectorAll('form').forEach(form => form.addEventListener('submit', handleSubmit));
  document.querySelector('#task-filter-date').addEventListener('change', renderTasks); document.querySelector('#task-today').addEventListener('click', () => { document.querySelector('#task-filter-date').value = localDate(); renderTasks(); });
  document.querySelector('#timer-toggle').addEventListener('click', () => { if (data.timer.runningSince !== null) { data.timer.accumulatedSec = timerSeconds(); data.timer.runningSince = null; showNotice('计时已暂停'); } else data.timer.runningSince = Date.now(); save(); renderAll(); });
  document.querySelector('#timer-finish').addEventListener('click', () => stopTimer(true)); document.querySelector('#timer-reset').addEventListener('click', () => { data.timer.accumulatedSec = 0; data.timer.runningSince = null; save(); renderAll(); showNotice('计时已清零'); }); document.querySelector('#timer-subject').addEventListener('change', e => { if (data.timer.runningSince === null) { data.timer.subjectId = e.target.value; save(); renderTimer(); } });
  document.querySelector('#export-button').addEventListener('click', exportBackup); document.querySelector('#import-file').addEventListener('change', async e => { const file = e.target.files[0]; if (!file) return; try { const incoming = parseBackup(await file.text()); if (!confirm('恢复后会覆盖当前全部记录，确定继续吗？')) return; data = incoming; save(); renderAll(); showNotice('备份已恢复'); } catch (err) { showNotice(err.message || '恢复失败', 'error'); } e.target.value = ''; });
  document.querySelector('#mistake-filter').addEventListener('change', renderMistakes);
  document.querySelector('#timer-subject').addEventListener('change', e => { data.timer.subjectId = e.target.value; save(); });
  document.addEventListener('click', event => { const el = event.target.closest('[data-go]'); if (el) go(el.dataset.go); const del = event.target.closest('[data-delete]'); if (del) { const fieldMap = { score: 'scores', task: 'tasks', session: 'sessions', mistake: 'mistakes', point: 'points' }; const field = fieldMap[del.dataset.delete]; if (!field) return; data[field] = data[field].filter(x => x.id !== del.dataset.id); save(); renderAll(); showNotice('已删除'); } const target = event.target.closest('[data-save-target]'); if (target) { const input = document.querySelector(`[data-target-subject="${target.dataset.saveTarget}"]`); const s = subject(target.dataset.saveTarget); const value = Number(input.value); if (value > 0 && value <= s.max) { s.target = value; save(); renderAll(); showNotice('目标分已更新'); } } const start = event.target.closest('[data-start-task]'); if (start) { const t = data.tasks.find(x => x.id === start.dataset.startTask); data.timer.subjectId = t.subjectId; data.timer.taskId = t.id; data.timer.runningSince = Date.now(); data.timer.accumulatedSec = 0; save(); go('timer'); showNotice('已开始任务计时'); } const review = event.target.closest('[data-review-mistake]'); if (review) { const m = data.mistakes.find(x => x.id === review.dataset.reviewMistake); m.reviewCount++; m.nextReview = nextReviewDate(localDate(), m.reviewCount); save(); renderAll(); showNotice(`已完成复习，下次安排在 ${dateLabel(m.nextReview)}`); } });
  document.addEventListener('change', event => { const task = event.target.closest('[data-toggle-task]'); if (task) { const t = data.tasks.find(x => x.id === task.dataset.toggleTask); t.done = task.checked; save(); renderAll(); } const point = event.target.closest('[data-point-status]'); if (point) { const p = data.points.find(x => x.id === point.dataset.pointStatus); p.status = point.value; save(); renderAll(); showNotice('掌握状态已更新'); } });
}

document.querySelector('#today-date').textContent = new Intl.DateTimeFormat('zh-CN', { year:'numeric', month:'long', day:'numeric', weekday:'long' }).format(new Date());
renderNav(); bindEvents(); go(currentPage);
if ('serviceWorker' in navigator) window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(() => {}));
window.addEventListener('beforeunload', () => { if (data.timer.runningSince !== null) { data.timer.accumulatedSec = timerSeconds(); save(); } });
